{
  "name": "Maryland Medical Assistance - Regular Medicaid/ABD",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "note": "Maryland’s ABD (Aged, Blind, Disabled) Medicaid uses very low monthly income limits. The available official Maryland materials in the search results show $350/month for one person and $392/month for a married couple/spouse case for ABD Medicaid.[4][5][14]",
      "household_table": [
        {
          "household_size": 1,
          "monthly_income_limit": "$350"
        },
        {
          "household_size": 2,
          "monthly_income_limit": "$392"
        }
      ],
      "important_caveat": "The state also distinguishes between categorically needy/regular ABD coverage and medically needy/spend-down pathways, so people above the basic income limit may still qualify through spend-down if they meet the program’s medically needy rules.[4][9]"
    },
    "asset_limits": {
      "note": "Official Maryland materials in the search results show ABD asset limits of $2,500 for one person and $3,000 for a married couple/spouse case.[4][5][14]",
      "household_table": [
        {
          "household_size": 1,
          "asset_limit": "$2,500"
        },
        {
          "household_size": 2,
          "asset_limit": "$3,000"
        }
      ],
      "what_counts": "Maryland’s general Medicaid materials indicate asset limits apply for age 65+, blind, disabled, or long-term-care-related eligibility.[1][6][12]",
      "what_is_exempt": "The search results do not provide a complete Maryland-specific exempt-asset list for ABD regular Medicaid, so the exact exemption list should be verified with the local agency before applying."
    },
    "other_requirements": [
      "Must be a Maryland resident.[1]",
      "Must be a U.S. citizen or a qualified non-citizen who meets immigration requirements.[1]",
      "Must meet the technical category requirement: age 65+, blind, or disabled.[1][6]",
      "Must meet the financial rules for the coverage group, including income and asset limits.[1][6]",
      "For some pathways, may need to meet medical eligibility for a certain level of care.[1][2]"
    ]
  },
  "benefits": {
    "type": "service",
    "value": "Regular Maryland Medical Assistance covers medically necessary health care for eligible ABD individuals, and Maryland LTSS coverage can include long-term care services and supports when the person qualifies medically and financially.[1][2][8][12] The search results specifically confirm nursing facility long-term care coverage for eligible low-income individuals and mention home-based and facility-based LTSS, but do not provide a single fixed dollar benefit amount because this is an insurance-style service program rather than a cash benefit.[2][8][11][12]",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online through Maryland’s myDHR portal (used for long-term care applications and related Medicaid applications).[11][13]",
      "In person at your local Department of Social Services office.[11][13]",
      "By mail to the appropriate county office or the Bureau of Long Term Care, depending on where you live and what type of long-term care application you are filing.[11]"
    ],
    "processing_time": "A written, telephonic, or electronic Medicaid application must be decided promptly, no later than 30 days after filing with the Department or its designee, or 10 days when filed with the local health department.[7]",
    "waitlist": null,
    "forms": [
      "The search results did not identify a specific standalone ABD form number.",
      "For long-term care applications, Maryland references a long-term care application submitted through myDHR or by paper/in-person routes.[11][13]"
    ],
    "documents": [
      "Proof of Maryland residency",
      "Proof of U.S. citizenship or qualified immigration status",
      "Proof of age (for ABD by age 65+)",
      "Medical proof of disability or blindness if applying under those categories",
      "Income proof such as Social Security, pension, wages, or other benefits",
      "Asset/bank statements and other resource records",
      "Health insurance cards and Medicare information if applicable",
      "Any long-term care or nursing facility records if applying for LTSS"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide program, but application routing for long-term care differs by county: Baltimore City and Anne Arundel, Baltimore, and Prince George’s counties use the Bureau of Long Term Care; other counties use the local department of social services.[11]",
    "regional_variations": "The core eligibility rules are statewide, but processing path and office handling for long-term care applications vary by region.[11] The search results do not show different eligibility rules by county, but they do show different intake offices and potentially different handling locations for certain applications.[11]",
    "offices_or_providers": [
      "Bureau of Long Term Care for Baltimore City and Anne Arundel, Baltimore, and Prince George’s counties.[11]",
      "Local Department of Social Services in other Maryland counties.[11]"
    ]
  },
  "official_source": "https://health.maryland.gov/mmcp/eligibility/Pages/generalrequirements.aspx",
  "gotchas": [
    "ABD Medicaid is not just age-based; the applicant also has to fit the disability/blindness/age category and the financial rules.[1][6]",
    "The income and asset limits are very low, and married couples have a different limit than single applicants.[4][5][14]",
    "People who are over the basic income limit may still qualify through medically needy/spend-down rules.[4][9]",
    "Long-term care Medicaid uses additional medical-necessity rules beyond basic ABD financial eligibility.[1][2][12]",
    "Application routing depends on county for long-term care cases, so families can send forms to different offices depending on where the person lives.[11]",
    "The search results do not show a single universal ABD form number or a complete exempt-asset list, so families should confirm details before filing."
  ],
  "data_shape_notes": "This program is statewide and category-based, but eligibility depends on a mix of age/disability status, very low income, and very low assets; long-term care applications also have county-specific intake paths and may involve spend-down or medical-necessity rules."
}

{
  "name": "Maryland Medical Assistance - Medically Needy Pathway",
  "eligibility": {
    "age": null,
    "income_limits": {
      "summary": "This is a non-MAGI Medicaid pathway for people whose income and resources are above other Medicaid categories but within Maryland's medically needy standards. Maryland's official schedule says the medically needy income standard for a household of 1 is $350/month ($4,200/year), and for 2 it is $392/month ($4,700/year); for 3 it is $434/month ($5,200/year), with the pattern continuing by household size in the state schedule.[4][11][15]",
      "table": [
        {
          "household_size": 1,
          "monthly_income_limit": 350,
          "annual_income_limit": 4200
        },
        {
          "household_size": 2,
          "monthly_income_limit": 392,
          "annual_income_limit": 4700
        },
        {
          "household_size": 3,
          "monthly_income_limit": 434,
          "annual_income_limit": 5200
        },
        {
          "household_size": 4,
          "monthly_income_limit": 475,
          "annual_income_limit": 5700
        }
      ],
      "notes": "Maryland uses a 6-month consideration period for medically needy spenddown; the state schedule shows the 6-month standard as $2,100 for 1 person, $2,350 for 2, $2,600 for 3, $2,850 for 4, and $3,126 for 5.[4][11]"
    },
    "asset_limits": {
      "summary": "Maryland's medically needy pathway includes a resource test, but the exact countable-resource limits depend on the category and are set in the Medicaid rules and schedules rather than in the broad eligibility page.[11][15]",
      "what_counts": [
        "countable resources / assets used for Medicaid eligibility determination",
        "income and resources are measured against medically needy standards[11][15]"
      ],
      "what_is_exempt": [
        "The official sources retrieved do not list the full exempt-asset list on the eligibility page; families should expect common Medicaid exemptions like a primary home and one vehicle to be evaluated under Maryland Medicaid rules, but the exact exemptions should be confirmed in the application review.[11][15]"
      ]
    },
    "other_requirements": [
      "Must fit a medically needy coverage group, such as aged, blind, disabled, child, or caretaker-relative medically needy categories.[15]",
      "Must be a Maryland resident and apply through Maryland Medicaid channels.[2][7]",
      "Must meet the spenddown/consideration-period rule if income is above the medically needy income standard.[4][11][15]",
      "The official Maryland page says eligibility also depends on income level, age, family size, and disability status depending on the coverage group.[7]"
    ]
  },
  "benefits": {
    "type": "service",
    "value": "Maryland Medical Assistance provides Medicaid coverage for eligible medically needy applicants; the sources retrieved do not identify a special cash amount, but instead describe coverage for Medicaid health services and long-term-care related eligibility categories.[9][15]",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online: https://www.marylandhealthconnection.gov",
      "App: Maryland Health Connection mobile app",
      "Phone: 1-855-642-8572",
      "In person: local health department",
      "In person: local department of social services",
      "Online for some applications: https://www.marylandbenefits.gov",
      "Mail: completed form to the local department of social services"
    ],
    "processing_time": "The official Maryland page says coverage can start right away if you are eligible, but it does not give a single fixed processing-time range for the medically needy pathway.[2]",
    "waitlist": null,
    "forms": [
      "Maryland Medical Assistance application (paper application used by local departments; the retrieved source identifies a 9701 application PDF, but the visible snippet does not provide a clearer public title beyond the application form itself).[12]"
    ],
    "documents": [
      "Proof of identity",
      "Proof of Maryland residency",
      "Social Security numbers for applicants",
      "Proof of income",
      "Proof of assets/resources",
      "Proof of age or disability if applying under an aged/blind/disabled medically needy category",
      "Information about household members and any current health coverage",
      "Any medical bills if using a spenddown/consideration-period route"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide Maryland program; applications are handled through Maryland Health Connection, local health departments, and local departments of social services.[2][9]",
    "regional_variations": "The core eligibility standard is statewide, but application handling can vary by office and local department. The retrieved sources do not show county-specific medically needy benefit differences or county-specific eligibility thresholds.[2][11]",
    "offices_or_providers": [
      "Maryland Health Connection",
      "Local health departments",
      "Local departments of social services"
    ]
  },
  "official_source": "https://health.maryland.gov/mmcp/eligibility/Pages/incomelimits.aspx",
  "gotchas": [
    "The medically needy pathway is not the same as regular MAGI Medicaid income-based eligibility; it is a non-MAGI route with a spenddown/consideration-period structure.[4][11][15]",
    "People with income above the monthly medically needy limit may still qualify if enough medical expenses are counted during the 6-month consideration period.[4][11][15]",
    "The income standard is very low compared with many families' expectations, so many applicants qualify only after medical-expense spenddown is applied.[4][15]",
    "The official eligibility page says the only way to know for sure is to apply, because income and asset limits are updated annually and exceptions can apply.[1]",
    "A family comparing this to nursing-home or long-term-care Medicaid should check whether the person is applying as aged/disabled medically needy, because the category affects the financial test.[15]"
  ],
  "data_shape_notes": "This program uses a medically needy spenddown model with a fixed statewide income standard and a 6-month consideration period, rather than a simple yes/no income cutoff.[4][11][15]"
}
